templates.code:
{expresión} > {umbral}
{expresión} > bool {umbral}
rate({counter}[{ventana}] offset {duración})

groups:
  - name: {grupo}
    interval: {intervalo}
    rules:
      - record: {nivel}:{métrica}:{operaciones}
        expr: {consulta}

- alert: {NombreDeAlerta}
  expr: {consulta} > {umbral}
  for: {espera}
  keep_firing_for: {retención}
  labels:
    severity: {severidad}
  annotations:
    summary: "{resumen}"
    description: "{detalle}: {{ $value }}"
    runbook_url: "{url}"

apiVersion: monitoring.coreos.com/v1
kind: PrometheusRule
metadata:
  name: {nombre}
  namespace: {namespace}
  labels:
    release: {release}
spec:
  groups:
    - name: {grupo}
      rules: […]

route:
  receiver: {receiver_por_defecto}
  group_by: [{label}, …]
  group_wait: {espera}
  group_interval: {intervalo}
  repeat_interval: {repetición}
  routes:
    - matchers: ['{label}="{valor}"']
      receiver: {receiver}
      continue: false

receivers:
  - name: {receiver}
    pagerduty_configs:
      - routing_key_file: {archivo}
  - name: {otro_receiver}
    slack_configs:
      - api_url_file: {archivo}
        channel: '{canal}'
        send_resolved: true

apiVersion: 1
datasources:
  - name: {nombre}
    type: prometheus
    uid: {uid}
    access: proxy
    url: http://{host}:9090
    isDefault: true
    jsonData:
      timeInterval: {scrape_interval}

Visualización: {Time series | Stat | Gauge | Heatmap | Table}
Unit: {s | ms | percentunit | reqps}
Thresholds: Base verde · {valor} rojo

apiVersion: 1
providers:
  - name: {nombre}
    type: file
    folder: {carpeta}
    allowUiUpdates: false
    options:
      path: {ruta_de_los_json}
